// Vinícius Machado · edição da fala dele (convite para café / networking) no estilo da VSL do G4 OS:
// fundo azul-petróleo escuro, serifa em caixa alta (branco + dourado), letras surgindo uma a uma, cortes secos entre
// a fala e cartões de texto, tela dividida (texto em cima, ele embaixo) e o nome em itálico sobre a imagem escurecida.
// Tempos = tempos das palavras na transcrição (src/video-1.mp4, 27,07 s). A voz é a do próprio vídeo (mix em tools/).
import { loadFont as loadSerif } from "@remotion/google-fonts/LibreBaskerville";
import { loadFont as loadSans } from "@remotion/google-fonts/Manrope";
import React from "react";
import {
  AbsoluteFill,
  Audio,
  interpolate,
  OffthreadVideo,
  Sequence,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from "remotion";

const { fontFamily: SERIF } = loadSerif("normal", { weights: ["400", "700"] });
const { fontFamily: SERIF_I } = loadSerif("italic", { weights: ["400"] });
const { fontFamily: SANS } = loadSans("normal", { weights: ["600", "700"] });

export const VM_FPS = 30;
export const VM_FRAMES = 812;
const s = (x: number) => Math.round(x * VM_FPS);

const NAVY_IN = "#12394e";
const NAVY_OUT = "#081a26";
const GOLD = "#d4b077";
const WHITE = "#f4efe6";
const CYAN = "#8fd8f2";
const EASE = Easing.bezier(0.22, 1, 0.36, 1);

const V = (n: string) => staticFile(`vinicius-machado/${n}`);

// ───────── texto: letras surgem uma a uma (opacidade + desfoque), depois ficam paradas ─────────
type Linha = { t: string; at: number; size: number; color?: string; font?: string; glow?: boolean; ls?: number; box?: boolean };

const Letras: React.FC<{ l: Linha; out?: number }> = ({ l, out }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const sec = f / fps;
  const per = Math.min(0.03, 0.42 / Math.max(1, l.t.length));
  const exitK = out === undefined ? 1 : interpolate(sec, [out - 0.16, out], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const color = l.color ?? WHITE;
  const chars = Array.from(l.t);
  const inner = chars.map((c, i) => {
    const k = interpolate(sec, [l.at + i * per, l.at + i * per + 0.16], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    return (
      <span key={i} style={{ opacity: k, filter: `blur(${(1 - k) * 10}px)`, whiteSpace: "pre" }}>
        {c}
      </span>
    );
  });
  const boxK = interpolate(sec, [l.at - 0.05, l.at + 0.2], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: EASE });
  return (
    <div
      style={{
        fontFamily: l.font ?? SERIF,
        fontWeight: l.font === SERIF_I ? 400 : 700,
        fontStyle: l.font === SERIF_I ? "italic" : "normal",
        fontSize: l.size,
        lineHeight: 1.08,
        letterSpacing: l.ls ?? 0.02 * l.size,
        color: l.box ? NAVY_OUT : color,
        textShadow: l.glow ? `0 0 ${l.size * 0.35}px rgba(232,190,120,.55), 0 2px 10px rgba(0,0,0,.5)` : l.box ? "none" : "0 2px 14px rgba(0,0,0,.35)",
        opacity: exitK,
        filter: `blur(${(1 - exitK) * 8}px)`,
        textAlign: "center",
        position: "relative",
        padding: l.box ? "8px 22px 6px" : 0,
        marginTop: l.box ? 10 : 0,
      }}
    >
      {l.box && (
        <div style={{ position: "absolute", inset: 0, background: GOLD, transformOrigin: "left center", transform: `scaleX(${boxK})` }} />
      )}
      <span style={{ position: "relative", fontStyle: l.box ? "italic" : undefined }}>{inner}</span>
    </div>
  );
};

const Bloco: React.FC<{ linhas: Linha[]; out?: number; top?: number; bottom?: number; gap?: number }> = ({ linhas, out, top, bottom, gap = 6 }) => (
  <AbsoluteFill
    style={{
      justifyContent: top === undefined && bottom === undefined ? "center" : bottom !== undefined ? "flex-end" : "flex-start",
      alignItems: "center",
      paddingTop: top,
      paddingBottom: bottom,
      paddingLeft: 120,
      paddingRight: 120,
      gap,
      flexDirection: "column",
    }}
  >
    {linhas.map((l, i) => (
      <Letras key={i} l={l} out={out} />
    ))}
  </AbsoluteFill>
);

// legenda pequena em sans, como a da referência
const Legenda: React.FC<{ t: string; at: number; out: number; y?: number }> = ({ t, at, out, y = 1230 }) => {
  const f = useCurrentFrame();
  const sec = f / VM_FPS;
  const k = interpolate(sec, [at, at + 0.12, out - 0.1, out], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <div
      style={{
        position: "absolute",
        top: y,
        left: 120,
        right: 120,
        textAlign: "center",
        fontFamily: SANS,
        fontWeight: 600,
        fontSize: 58,
        color: WHITE,
        opacity: k,
        textShadow: "0 2px 12px rgba(0,0,0,.85), 0 0 3px rgba(0,0,0,.6)",
      }}
    >
      {t}
    </div>
  );
};

// ───────── fundo dos cartões: azul-petróleo liso, anéis entrelaçados muito apagados derivando devagar ─────────
const Fundo: React.FC<{ drift?: number; ring?: boolean }> = ({ drift = 0, ring = true }) => {
  const f = useCurrentFrame();
  const r = f * 0.06 + drift;
  return (
    <AbsoluteFill style={{ background: `radial-gradient(ellipse 80% 60% at 50% 45%, ${NAVY_IN} 0%, #0d2b3c 45%, ${NAVY_OUT} 100%)` }}>
      {ring && (
        <svg width={1080} height={1920} style={{ position: "absolute", opacity: 0.075 }}>
          <g transform={`translate(${540 + Math.sin((f + drift * 10) / 70) * 30} ${960 + Math.cos((f + drift * 10) / 90) * 26}) rotate(${r - 18})`}>
            <circle cx={-190} cy={0} r={330} fill="none" stroke="#6fb4d6" strokeWidth={56} />
            <circle cx={190} cy={0} r={330} fill="none" stroke="#6fb4d6" strokeWidth={56} />
          </g>
        </svg>
      )}
    </AbsoluteFill>
  );
};

// ───────── fala dele em tela cheia ─────────
type Cam = { from: number; to: number; x0?: number; x1?: number; y0?: number; y1?: number; punch?: boolean };
const Fala: React.FC<{ startSec: number; dur: number; cam: Cam; dim?: number; grad?: boolean }> = ({ startSec, dur, cam, dim = 0, grad = true }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = interpolate(f, [0, dur], [0, 1], { extrapolateRight: "clamp" });
  let sc = interpolate(p, [0, 1], [cam.from, cam.to]);
  if (cam.punch) sc *= 1 + 0.09 * (1 - spring({ frame: f, fps, config: { damping: 16, stiffness: 160 } }));
  const x = interpolate(p, [0, 1], [cam.x0 ?? 0, cam.x1 ?? 0]);
  const y = interpolate(p, [0, 1], [cam.y0 ?? 0, cam.y1 ?? 0]);
  return (
    <AbsoluteFill style={{ background: "#000", overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `translate(${x}px, ${y}px) scale(${sc})`, transformOrigin: "50% 38%" }}>
        <OffthreadVideo src={V("video-1.mp4")} muted trimBefore={s(startSec)} style={{ width: 1080, height: 1920, filter: "contrast(1.06) saturate(0.95)" }} />
      </AbsoluteFill>
      {dim > 0 && <AbsoluteFill style={{ background: `rgba(8,26,38,${dim})` }} />}
      {grad && <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(0,0,0,0) 48%, rgba(6,18,27,.55) 72%, rgba(6,18,27,.85) 100%)" }} />}
    </AbsoluteFill>
  );
};

// entrada de cena: cada uma de um jeito
const Entrada: React.FC<{ kind: "blur" | "cut" | "wipe" | "zoom" | "slide" | "fade"; children: React.ReactNode }> = ({ kind, children }) => {
  const f = useCurrentFrame();
  const k = interpolate(f, [0, 7], [0, 1], { extrapolateRight: "clamp", easing: EASE });
  let style: React.CSSProperties = {};
  if (kind === "blur") style = { filter: `blur(${(1 - k) * 22}px)`, transform: `scale(${1 + (1 - k) * 0.06})` };
  if (kind === "zoom") style = { filter: `blur(${(1 - k) * 14}px)`, transform: `scale(${1.25 - 0.25 * k})` };
  if (kind === "wipe") style = { clipPath: `inset(${(1 - k) * 100}% 0 0 0)` };
  if (kind === "slide") style = { transform: `translateX(${(1 - k) * 1080}px)` };
  if (kind === "fade") style = { opacity: k };
  return <AbsoluteFill style={style}>{children}</AbsoluteFill>;
};

// ───────── desenhos ─────────
const Xicara: React.FC<{ at: number }> = ({ at }) => {
  const f = useCurrentFrame();
  const sec = f / VM_FPS;
  const d = interpolate(sec, [at, at + 0.5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: EASE });
  const st = (len: number) => ({ strokeDasharray: len, strokeDashoffset: len * (1 - d) });
  const steam = (i: number) => {
    const ph = f / 9 + i * 2;
    const k = interpolate(sec, [at + 0.3 + i * 0.08, at + 0.6 + i * 0.08], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    const x = -60 + i * 60;
    return (
      <path
        key={i}
        d={`M ${x} -40 C ${x + 22 * Math.sin(ph)} -90, ${x - 22 * Math.sin(ph)} -130, ${x + 10 * Math.sin(ph + 1)} -180`}
        fill="none"
        stroke={WHITE}
        strokeWidth={9}
        strokeLinecap="round"
        opacity={0.55 * k * (0.75 + 0.25 * Math.sin(ph))}
      />
    );
  };
  return (
    <svg width={520} height={420} viewBox="-260 -220 520 420" style={{ overflow: "visible" }}>
      {[0, 1, 2].map(steam)}
      <path d="M -150 -20 L 150 -20 L 128 120 Q 120 160 80 160 L -80 160 Q -120 160 -128 120 Z" fill="none" stroke={GOLD} strokeWidth={12} strokeLinejoin="round" style={st(960)} />
      <path d="M 145 10 Q 225 10 220 70 Q 214 120 132 116" fill="none" stroke={GOLD} strokeWidth={12} strokeLinecap="round" style={st(260)} />
      <path d="M -210 196 L 210 196" stroke={GOLD} strokeWidth={12} strokeLinecap="round" style={st(420)} />
    </svg>
  );
};

const Rede: React.FC<{ at: number }> = ({ at }) => {
  const f = useCurrentFrame();
  const sec = f / VM_FPS;
  const rot = f * 0.12;
  const N = 7;
  const pts = Array.from({ length: N }, (_, i) => {
    const a = (i / N) * Math.PI * 2 - Math.PI / 2;
    const r = i % 2 ? 250 : 300;
    return [Math.cos(a) * r, Math.sin(a) * r * 0.82];
  });
  const k = (i: number) => interpolate(sec, [at + i * 0.13, at + i * 0.13 + 0.3], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: EASE });
  const centro = spring({ frame: f - s(at - 0.35), fps: VM_FPS, config: { damping: 12, stiffness: 170 } });
  return (
    <svg width={760} height={620} viewBox="-380 -310 760 620" style={{ overflow: "visible" }}>
      <g transform={`rotate(${rot})`}>
        {pts.map(([x, y], i) => {
          const [nx, ny] = pts[(i + 1) % N];
          const kk = k(i);
          const kr = k(i + 2);
          return (
            <g key={i}>
              <line x1={0} y1={0} x2={x * kk} y2={y * kk} stroke={GOLD} strokeWidth={5} opacity={0.75} />
              <line x1={x} y1={y} x2={x + (nx - x) * kr} y2={y + (ny - y) * kr} stroke="#6fb4d6" strokeWidth={4} opacity={0.5 * kr} />
            </g>
          );
        })}
        {pts.map(([x, y], i) => {
          const kk = spring({ frame: f - s(at + i * 0.13 + 0.2), fps: VM_FPS, config: { damping: 11, stiffness: 190 } });
          return (
            <g key={`n${i}`} transform={`translate(${x} ${y}) rotate(${-rot}) scale(${kk})`}>
              <circle r={34} fill={NAVY_OUT} stroke={WHITE} strokeWidth={6} />
              <circle cy={-8} r={9} fill={WHITE} />
              <path d="M -16 18 Q 0 -4 16 18" fill={WHITE} />
            </g>
          );
        })}
        <g transform={`rotate(${-rot}) scale(${centro})`}>
          <circle r={62} fill={GOLD} />
          <circle cy={-14} r={17} fill={NAVY_OUT} />
          <path d="M -30 34 Q 0 -8 30 34" fill={NAVY_OUT} />
        </g>
      </g>
    </svg>
  );
};

const BotaoSaibaMais: React.FC<{ at: number; click: number }> = ({ at, click }) => {
  const f = useCurrentFrame();
  const sec = f / VM_FPS;
  const inK = spring({ frame: f - s(at), fps: VM_FPS, config: { damping: 13, stiffness: 170 } });
  const cur = interpolate(sec, [at + 0.05, click], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: EASE });
  const press = interpolate(sec, [click, click + 0.08, click + 0.22], [1, 0.93, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const fill = interpolate(sec, [click, click + 0.15], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const ring = interpolate(sec, [click, click + 0.5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <div style={{ position: "relative", width: 640, height: 150, transform: `scale(${inK * press})` }}>
      <div
        style={{
          position: "absolute",
          inset: -24 * ring,
          borderRadius: 30 + 24 * ring,
          border: `4px solid ${GOLD}`,
          opacity: ring > 0 ? 1 - ring : 0,
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 30,
          border: `5px solid ${GOLD}`,
          background: `rgba(212,176,119,${fill})`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: SANS,
          fontWeight: 700,
          fontSize: 62,
          letterSpacing: 2,
          color: fill > 0.5 ? NAVY_OUT : WHITE,
        }}
      >
        Saiba mais
      </div>
      <svg
        width={120}
        height={140}
        viewBox="0 0 24 28"
        style={{ position: "absolute", left: 470 + (1 - cur) * 260, top: 70 + (1 - cur) * 300, opacity: cur > 0 ? 1 : 0, transform: `scale(${press})` }}
      >
        <path d="M2 1 L2 21 L7 16.5 L10.5 24.5 L14 23 L10.6 15.2 L17 15.2 Z" fill={WHITE} stroke={NAVY_OUT} strokeWidth={1.4} strokeLinejoin="round" />
      </svg>
    </div>
  );
};

const Formulario: React.FC<{ at: number }> = ({ at }) => {
  const f = useCurrentFrame();
  const sec = f / VM_FPS;
  const inK = spring({ frame: f - s(at), fps: VM_FPS, config: { damping: 14, stiffness: 150 } });
  const campo = (i: number) => {
    const k = interpolate(sec, [at + 0.25 + i * 0.32, at + 0.55 + i * 0.32], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: EASE });
    const ok = spring({ frame: f - s(at + 0.55 + i * 0.32), fps: VM_FPS, config: { damping: 12, stiffness: 200 } });
    return (
      <div key={i} style={{ height: 92, borderRadius: 18, border: "3px solid rgba(244,239,230,.35)", display: "flex", alignItems: "center", padding: "0 30px", gap: 24 }}>
        <div style={{ height: 18, borderRadius: 9, background: WHITE, opacity: 0.85, width: `${[62, 74, 54][i] * k}%` }} />
        <div style={{ flex: 1 }} />
        <div style={{ width: 46, height: 46, borderRadius: 23, background: GOLD, transform: `scale(${ok})`, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <svg width={26} height={26} viewBox="0 0 24 24">
            <path d="M5 12.5 L10 17 L19 7" fill="none" stroke={NAVY_OUT} strokeWidth={3.4} strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </div>
      </div>
    );
  };
  return (
    <div
      style={{
        width: 680,
        padding: "44px 44px",
        borderRadius: 34,
        background: "rgba(8,26,38,.75)",
        border: `3px solid ${GOLD}`,
        display: "flex",
        flexDirection: "column",
        gap: 26,
        transform: `scale(${0.85 + 0.15 * inK})`,
        opacity: inK,
        boxShadow: "0 30px 80px rgba(0,0,0,.45)",
      }}
    >
      {[0, 1, 2].map(campo)}
    </div>
  );
};

// ───────── cenas ─────────
// [início, fim] em segundos
const C = {
  a: [0, 2.75],
  b: [2.75, 4.62],
  c: [4.62, 6.93],
  d: [6.93, 11.47],
  e: [11.47, 12.95],
  f: [12.95, 15.88],
  g: [15.88, 18.02],
  h: [18.02, 21.62],
  i: [21.62, 25.25],
  j: [25.25, 26.18],
  k: [26.18, 27.07],
} as const;

const Cena: React.FC<{ c: readonly [number, number]; children: React.ReactNode }> = ({ c, children }) => (
  <Sequence from={s(c[0])} durationInFrames={s(c[1]) - s(c[0])}>
    {children}
  </Sequence>
);
// mostra só entre dois tempos absolutos, sem mudar o relógio de dentro
const Janela: React.FC<{ from?: number; to?: number; children: React.ReactNode }> = ({ from = -1, to = 1e9, children }) => {
  const sec = useCurrentFrame() / VM_FPS;
  return sec >= from && sec < to ? <>{children}</> : null;
};
// texto de dentro de uma cena usa tempo absoluto: desloca pelo começo da cena
const Abs: React.FC<{ c: readonly [number, number]; children: React.ReactNode }> = ({ c, children }) => (
  <Sequence from={-s(c[0])}>{children}</Sequence>
);

export const ViniciusMachado: React.FC = () => {
  return (
    <AbsoluteFill style={{ background: NAVY_OUT }}>
      {/* A · Empresários que crescem de verdade */}
      <Cena c={C.a}>
        <Fala startSec={C.a[0]} dur={s(2.75)} cam={{ from: 1.02, to: 1.08, punch: true }} />
        <Abs c={C.a}>
          <Bloco
            bottom={380}
            gap={4}
            linhas={[
              { t: "EMPRESÁRIOS QUE", at: 0.25, size: 56 },
              { t: "CRESCEM", at: 1.35, size: 128, color: GOLD, glow: true },
              { t: "DE VERDADE", at: 1.87, size: 80, color: GOLD, glow: true },
            ]}
          />
        </Abs>
      </Cena>

      {/* B · não fazem tudo sozinhos */}
      <Cena c={C.b}>
        <Entrada kind="blur">
          <Fundo drift={0} />
          <Abs c={C.b}>
            <Bloco
              gap={14}
              linhas={[
                { t: "NÃO FAZEM TUDO", at: 2.81, size: 58 },
                { t: "SOZINHOS", at: 3.87, size: 124, color: GOLD },
              ]}
            />
          </Abs>
        </Entrada>
      </Cena>

      {/* C · Eles compartilham experiências — título embaixo, sem escurecer a imagem (v2: sem o nome; v4: fora do rosto e sem a película escura) */}
      <Cena c={C.c}>
        <Fala startSec={C.c[0]} dur={s(2.31)} cam={{ from: 1.16, to: 1.1, x0: 20, x1: -20 }} grad={false} />
        <Abs c={C.c}>
          <Bloco
            bottom={380}
            gap={8}
            linhas={[
              { t: "ELES COMPARTILHAM", at: 4.73, size: 56 },
              { t: "EXPERIÊNCIAS", at: 5.86, size: 86, color: GOLD, glow: true },
            ]}
          />
        </Abs>
      </Cena>

      {/* D · aprendem uns com os outros e fazem negócios juntos — tela dividida */}
      <Cena c={C.d}>
        <Entrada kind="wipe">
          <Fundo drift={40} ring={false} />
          <div style={{ position: "absolute", left: 0, right: 0, top: 960, height: 960, overflow: "hidden" }}>
            <div style={{ position: "absolute", top: -330, left: 0, width: 1080, height: 1920 }}>
              <Fala startSec={C.d[0]} dur={s(4.54)} cam={{ from: 1.0, to: 1.07 }} grad={false} />
            </div>
            <AbsoluteFill style={{ background: `linear-gradient(180deg, ${NAVY_OUT} 0%, rgba(8,26,38,0) 22%)` }} />
          </div>
          <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 960 }}>
            <Abs c={C.d}>
              <Bloco
                out={9.2}
                gap={10}
                linhas={[
                  { t: "APRENDEM", at: 6.97, size: 60 },
                  { t: "UNS COM", at: 7.86, size: 104, color: GOLD },
                  { t: "OS OUTROS", at: 8.38, size: 104, color: GOLD },
                ]}
              />
              <Janela from={9.22}>
                <Bloco
                  gap={10}
                  linhas={[
                    { t: "E FAZEM", at: 9.26, size: 60 },
                    { t: "NEGÓCIOS", at: 9.98, size: 118, color: GOLD },
                    { t: "JUNTOS", at: 10.84, size: 58, box: true, ls: 8 },
                  ]}
                />
              </Janela>
            </Abs>
          </div>
        </Entrada>
      </Cena>

      {/* E · Venha tomar um café comigo */}
      <Cena c={C.e}>
        <Entrada kind="zoom">
          <Fundo drift={80} />
          <Abs c={C.e}>
            <Bloco
              top={470}
              gap={8}
              linhas={[
                { t: "VENHA TOMAR", at: 11.52, size: 60 },
                { t: "UM CAFÉ", at: 11.98, size: 128, color: GOLD },
                { t: "COMIGO", at: 12.3, size: 60, color: CYAN, ls: 10 },
              ]}
            />
            <AbsoluteFill style={{ alignItems: "center", justifyContent: "flex-start", paddingTop: 1000 }}>
              <div style={{ transform: "scale(1.25)", transformOrigin: "top center" }}><Xicara at={11.62} /></div>
            </AbsoluteFill>
          </Abs>
        </Entrada>
      </Cena>

      {/* F · Vamos aumentar a nossa rede de relacionamentos */}
      <Cena c={C.f}>
        <Entrada kind="slide">
          <Fundo drift={120} ring={false} />
          <Abs c={C.f}>
            <Bloco
              top={330}
              gap={8}
              linhas={[
                { t: "VAMOS AUMENTAR A NOSSA", at: 13.04, size: 46, ls: 3 },
                { t: "REDE", at: 14.54, size: 150, color: GOLD },
                { t: "DE RELACIONAMENTOS", at: 14.94, size: 50, ls: 3 },
              ]}
            />
            <AbsoluteFill style={{ alignItems: "center", justifyContent: "flex-start", paddingTop: 900 }}>
              <div style={{ transform: "scale(1.1)", transformOrigin: "top center" }}><Rede at={13.5} /></div>
            </AbsoluteFill>
          </Abs>
        </Entrada>
      </Cena>

      {/* G · e quem sabe possamos fazer negócios */}
